 private final BuyReplacementExpectedSlotOccupancyEvaluation source; private final double driftFraction; private final int exitPrice; private final int exitTaxPerItem; private final long lossPerItem; private final long totalUnwindLoss;
 BuyReplacementUnwindLossEvaluation(BuyReplacementExpectedSlotOccupancyEvaluation s,double d,int x,int t,long l,long total){source=s;driftFraction=d;exitPrice=x;exitTaxPerItem=t;lossPerItem=l;totalUnwindLoss=total;}
 int getBuyOffsetIndex(){return source.getBuyOffsetIndex();} double getBuyOffset(){return source.getBuyOffset();} int getBuyPrice(){return source.getBuyPrice();} int getExactRemainderQuantity(){return source.getExactRemainderQuantity();} long getTotalCost(){return source.getTotalCost();} int getSellOffsetIndex(){return source.getSellOffsetIndex();} double getSellOffset(){return source.getSellOffset();} int getSellPrice(){return source.getSellPrice();} long getNetMarginPerItem(){return source.getNetMarginPerItem();} long getTotalNetMargin(){return source.getTotalNetMargin();} double getBuyProbability(){return source.getBuyProbability();} double getSellProbability(){return source.getSellProbability();} double getCompletionProbability(){return source.getCompletionProbability();} double getExpectedSlotHours(){return source.getExpectedSlotHours();} double getDriftFraction(){return driftFraction;} int getExitPrice(){return exitPrice;} int getExitTaxPerItem(){return exitTaxPerItem;} long getLossPerItem(){return lossPerItem;} long getTotalUnwindLoss(){return totalUnwindLoss;}
